#!/bin/bash
# Mac test of our menu bar's height and the window geometry from it (common/MenuBarHeight.h, test-menubarheight.c; 1.7.1 item 14: on Home-button
# iPads windows and tiles started 3-4 pt below the 20 pt bar), then the sites in the code as built: every one takes the bar's height.
set -e
cd "$(dirname "$0")"
W=$(mktemp -d); trap 'rm -rf "$W"' EXIT
clang -O2 -Wall -Wno-unused-function -o "$W/tmbh" test-menubarheight.c
"$W/tmbh"
fails=0
check() { if eval "$2"; then echo "PASS  $1"; else echo "FAIL  $1"; fails=1; fi; }
S=../statusbar/StatusBar.x
check "DMTopLimit: the bar's height (0 while it hides itself)" "grep -q 'static CGFloat DMTopLimit(void) { return DMAutoHideLayout() ? 0.0 : MSBDMenuBarTopLimit(DMMenuBarHeight()); }' $S"
check "item 9: saved windows of Aerial / Zetsu / MilkyWay4 re-fitted from the pre-1.7.1 top (23: one point into the 24 pt bar), not today's MSBDMenuBarTopLimit(24)" "grep -q 'MSBDMenuBarRefitTop(&y, &h, kMSBDMenuBarDefault - 1.0, MSBDMenuBarTopLimit(DMMenuBarHeight()),' $S"
check "DMMenuBarHeight: iOS's provider (+height, type-checked) or the copy's height, on the main screen, 24 until known (the size's at Medium / Large, 1.7.3)" \
  "awk '/^static CGFloat DMMenuBarHeight\\(void\\) \\{/{f=1} f&&/fg.window.screen != \\[UIScreen mainScreen\\]/{a=1} f&&/\"d16@0:8\"/{b=1} f&&/MSBDMenuBarHeightOf\\(provided, fg.bounds.size.height\\)/{c=1} f&&/return DMMenuBarUnknownHeight\\(\\);/{d=1} f&&/^}/{print (a&&b&&c&&d) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
check "Stage Manager: the stage starts under the bar's height, not at least 24 (the _statusBarHeight hook)" "grep -q 'return DMSMEngine() ? MAX(h, DMMenuBarHeight()) + ' $S && ! grep -q 'MAX(h, 24.0)' $S"
check "Stage Manager: our usable area on the iPad starts at the bar's height" "awk '/^static CGRect DMSMUsableAreaForIdentity\\(id identity, CGSize \\*screenOut\\) \\{/{f=1} f&&/CGFloat bar = DMMenuBarHeight\\(\\);/{a=1} f&&/if \\(CGRectGetMinY\\(u\\) < bar\\)/{b=1} f&&/^}/{print (a&&b) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
check "Stage Manager: the size grid's tallest window leaves the bar of its screen (both grids)" "[ \$(grep -c 'dock.doubleValue - 2.0 - (DMSMTopBarOf(b.size) + kSMBarH)' $S) = 2 ] && ! grep -q '(24.0 + kSMBarH)' $S"
check "the center layout and MilkyWay4's default place: 12 pt under the bar" "grep -q 'MSBDMenuBarCenterTop(DMMenuBarHeight()) : 36.0;' $S && grep -q 'CGRectMake(round(screen.width \\* 0.11), MSBDMenuBarCenterTop(DMMenuBarHeight()), round(screen.width \\* 0.78)' $S"
check "auto-hide: windows move down by at least the bar's height, and its top band follows the bar" "grep -q 'CGFloat h = DMMenuBarHeight();' $S && grep -q 'fabs(f.origin.y - MSBDMenuBarWasTop(bar)) < 2.0' $S && grep -q 'f.origin.y < MSBDMenuBarUnderTop(bar)' $S"
check "auto-hide: the top-edge strip sits at the screen's top edge -- placed through the screen's space (iPadOS 16 keeps its window portrait and turned: the window's own top was a side edge in landscape), when it comes on and on every tick while the bar is hidden (1.7.3 device pass)" \
  "grep -q 'CGRect r = \\[gSBEdgeWindow convertRect:CGRectMake(0, 0, s.bounds.size.width, 6.0) fromCoordinateSpace:s.coordinateSpace\\];' $S && grep -q 'if (on) DMEdgeStripPlace();' $S && grep -q 'if (gSBHidden) DMEdgeStripPlace();' $S && [ \$(grep -c 'gSBEdgeStrip.frame = ' $S) = 1 ] && ! grep -q 'strip.autoresizingMask = UIViewAutoresizingFlexibleWidth;' $S"
check "native windows: a touch on the bar is judged by the bar's height" "grep -q 'if (p.y < MSBDMenuBarTouchBand(DMMenuBarHeight())) return;' ../statusbar/NativeWindow.h"
# ---- 1.7.3 Menu Bar Size (common/MenuBarSize.h) ----
P=../statusbar/macstatusbarprefs
check "Menu Bar Size: Small hooks nothing (DMBarSizeInit returns before any %init)" \
  "awk '/^static void DMBarSizeInit\\(void\\) \\{/{f=1} f&&/if \\(want == MSBDMenuBarSmall\\) \\{ DMLog/{a=NR} f&&/%init\\(/{if(!b)b=NR} f&&/^}/{print (a&&b&&a<b) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
check "Menu Bar Size: set up before SpringBoard's first bar -- in %ctor after the stock status bar's return, before the bar's own hooks" \
  "awk '/^%ctor \\{/{f=1} f&&/if \\(gStockBar\\) \\{/{a=NR} f&&/DMBarSizeInit\\(\\);/{b=NR} f&&/%init\\(_UIStatusBarForegroundView = DMSBClass/{c=NR; print (a&&b&&a<b&&b<c) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
check "Menu Bar Size: a provider family is hooked only with every method its own and of the types read (height, baselineOffset, normalFont, styleAttributesForStyle:)" \
  "grep -q 'DMBarSizeOwns(pad, YES, \"height\", \"d16@0:8\") && DMBarSizeOwns(pad, YES, \"baselineOffset\", \"d16@0:8\")' $S && grep -q 'DMBarSizeOwns(rounded, YES, \"height\", \"d16@0:8\") && DMBarSizeOwns(rounded, YES, \"baselineOffset\", \"d16@0:8\")' $S && grep -q 'DMBarSizeOwns(pad, NO, \"normalFont\", \"@16@0:8\") && DMBarSizeOwns(pad, NO, \"styleAttributesForStyle:\", \"@24@0:8q16\")' $S && grep -q 'if (DMBarSizeOwns(pad, NO, \"clockFont\", \"@16@0:8\")) {' $S"
check "Menu Bar Size: in force only when SpringBoard's own family went on (17+ SystemStatusUI, 15/16 UIKit), else Small for everything" \
  "grep -q 'if (!(stui ? went\\[1\\] : went\\[0\\])) {' $S && grep -q 'gDMBarSize = MSBDMenuBarSmall;   // (SpringBoard' $S"
check "Menu Bar Size: a TV's provider (an _ExternalPad, either family) keeps the normal bar" \
  "grep -q 'return !((extUIKit && \\[c isSubclassOfClass:extUIKit\\]) || (extSTUI && \\[c isSubclassOfClass:extSTUI\\]));' $S && [ \$(grep -c 'return DMBarSizeHeightFor(self, h);' $S) = 4 ] && grep -q 'static double DMBarSizeHeightFor(Class c, double stock) { return DMBarSizeClass(c) \&\& !gDMBarStockDepth ? MSBDMenuBarSizeHeight(gDMBarSize, stock) : stock; }' $S"
check "Menu Bar Size: iOS's text scaled once (a font hook inside another leaves it to the outer one), its icon scale type-checked and once per object" \
  "grep -q 'static BOOL DMBarSizeFontWanted(id provider) { return !gDMBarFontDepth && DMBarSizeClass(object_getClass(provider)); }' $S && grep -q 'strcmp(method_getTypeEncoding(g) ?: \"\", \"d16@0:8\") || strcmp(method_getTypeEncoding(s) ?: \"\", \"v24@0:8d16\")' $S && grep -q 'objc_setAssociatedObject(attrs, kBarSizeScaledKey, @YES' $S"
check "Menu Bar Size: iOS's text never scaled twice (a font at the size's text already goes back as it is)" \
  "grep -q 'if (pt >= kMSBDMenuBarStockText \\* k - 0.01) return f;' $S && grep -q 'return \\[(UIFont \\*)f fontWithSize:pt \\* k\\];' $S"
check "Menu Bar Size: the bar's height not known yet is the size's (24 at Small, as before)" \
  "grep -q 'static CGFloat DMMenuBarUnknownHeight(void) { return MSBDMenuBarSizeHeight(gDMBarSize, kMSBDMenuBarDefault); }' $S && ! grep -q 'return kMSBDMenuBarDefault;' $S"
check "Menu Bar Size: item 9's re-fit stays for bars shorter than 24 only (a taller bar is no old 24 pt top)" "grep -q 'if (!(gDMMenuBarH > 0) || gDMMenuBarH >= kMSBDMenuBarDefault - 0.25) return NO;' $S"
check "Menu Bar Size: our items x the copy's scale -- 1 at Small and on a TV's bar" \
  "grep -q 'return s && s != \\[UIScreen mainScreen\\] ? MSBDMenuBarSmall : gDMBarSize;' $S && grep -q 'CGFloat targetInk = MSBDMenuBarLogoInk(copySize, fg.bounds.size.height, timeFont.pointSize);' $S && [ \$(grep -c 'kTitleGap \\* k' $S) = 8 ] && grep -q 'kSpotClockGap \\* k' $S && grep -q 'kClockIconsGap \\* k' $S && grep -q 'kLogoHitSlop \\* k' $S && grep -q 'lights.scale = k;' $S && grep -q 'CGFloat k = DMBarItemScale(fg);   // (Menu Bar Size, 1.7.3: its touch area' $S"
check "Menu Bar Size: our Wi-Fi and mute icons at the copy's scale (the SSH, Spotlight and VPN icons from the text / x k)" \
  "grep -q 'left = DMWiFiLayoutIcon(fg, left, timeCentre.y, k);' $S && grep -q 'UIImage \\*glyph = DMMuteGlyph(DMWiFiIconHeight(k));' $S && grep -q 'static CGFloat DMWiFiIconHeight(CGFloat k) { return round(2.0 \\* kWiFiIconH \\* k) / 2.0; }' ../statusbar/WiFiMenu.h && grep -q 'CGFloat w = ceil(vpnIcon.image.size.width \\* k), h = ceil(vpnIcon.image.size.height \\* k);' $S"
check "Menu Bar Size: menus -- rows, separators, the panel's width and the rows' text from the size" \
  "grep -q '    if (it == \\[NSNull null\\]) return DMMenuSepH();' $S && grep -q '    return gPanelRowH > 0.0 ? gPanelRowH : DMMenuRowH();' $S && grep -q '_label.font = \\[UIFont systemFontOfSize:DMMenuTextPt()\\];' $S && grep -q 'CGFloat panelW = DMMenuPanelW();' $S && ! grep -q 'kPanelW, h)\\]' $S"
check "Menu Bar Size: the places that took a fixed 24 keep it at Small, take the bar at Medium / Large (banners, keyboard pill, Stage Manager note, Wi-Fi menu room, auto-hide band)" \
  "grep -q 'static CGFloat DMBannerTop(void) { return MSBDMenuBarFixedSite(gDMBarSize, DMMenuBarHeight()) + 8.0; }' $S && grep -q 'MSBDMenuBarFixedSite(gDMBarSize, DMMenuBarHeight()) / 2.0);' $S && grep -q 'MSBDMenuBarFixedSite(gDMBarSize, DMMenuBarHeight()) + 14.0' ../statusbar/MacSwitcherSM.h && grep -q 'MSBDMenuBarFixedSite(gDMBarSize, DMMenuBarHeight()) + 16.0' ../statusbar/WiFiMenu.h && grep -q 'const CGFloat touching = MSBDMenuBarFixedSite(gDMBarSize, DMMenuBarHeight()) - 1.0;' $S && [ \$(grep -c 'top < touching' $S) = 3 ] && ! grep -q 'top < 23.0' $S && ! grep -q '24.0 + 14.0' ../statusbar/MacSwitcherSM.h"
check "Menu Bar Size: the saved windows remember their bar and are re-fitted under a bar of another size (not while it hides itself)" \
  "grep -q 'if (DMMenuBarKnownHeight() > 0) saving\\[@\"bar\"\\] = @(DMMenuBarKnownHeight());' $S && grep -q 'gRestoreRefitSize = !DMAutoHideLayout() && MSBDMenuBarRefitWanted(' $S && grep -q 'if (MSBDMenuBarRefitSize(&y, &h, placed ? MSBDMenuBarTopLimit(placed.doubleValue) : NAN, MSBDMenuBarTopLimit(DMMenuBarHeight()),' $S"
check "Menu Bar Size: Stage Manager's stages re-fitted once under a bar of another size (stagesMenuBar), after item 9's step" \
  "grep -q 'sized = MSBDMenuBarRefitWanted(placed, gDMMenuBarH, gDMBarSize);' $S && grep -q 'if (sized && MSBDMenuBarRefitSize(&y, &h, placedTop, DMMenuBarHeight(), CGRectGetMaxY(u), MSBDWindowMinSize().height)) moved = YES;' $S && grep -q 'DMSMSaveStages(); DMRefitTopDone(2); DMSMNoteStagesBar(); });' $S"
check "Menu Bar Size: a Stage Manager window of its own (default) size is measured by its card on screen for the re-fit (not skipped)" \
  "grep -q 'static id DMSMAttrsRefitTop(id attrs, NSString \\*key, BOOL old24, BOOL sized, double placedTop) {' $S && grep -q 'if ((pts.width <= 0 || pts.height <= 0) && sized && key) {' $S && grep -q 'UIView \\*card = DMSMCardFor(key);' $S && grep -q 'id a = DMSMAttrsRefitTop(m\\[it\\], k, old24, sized == 1, placedTop);' $S"
check "Menu Bar Size: the bar's menus fit the room under the bar (shorter rows, never below Small's), the Apple menu and every other" \
  "[ \$(grep -c 'UIView \\*panel = DMMakeBarMenuPanel(items, host, anchor);' $S) = 2 ] && grep -q 'CGFloat rowH = MSBDMenuRowFit(DMMenuRowH(), rows, other, room);' $S && grep -q 'CGFloat room = host.bounds.size.height - (CGRectGetMaxY(anchor) + 2.0) - kPanelPad;' $S && grep -q '    gPanelRowH = 0.0;' $S"
check "Menu Bar Size: BigSurCenter's panel drawn lower by the bar's growth (iOS's own height of the bar, as DMMenuBarHeight read it), its height cap with it" \
  "grep -q 'static CGFloat DMMenuBarStockHeight(void) { return gDMMenuBarStockH; }' $S && grep -q 'static CGFloat DMCCPanelShift(void) { return MSBDCCPanelShift(gDMBarSize, DMMenuBarHeight(), DMMenuBarStockHeight()); }' $S && grep -q 'if (down > 0.0) want = CATransform3DConcat(want, CATransform3DMakeTranslation(0.0, down, 0.0));' $S && grep -q '(MIN(screen.size.width, screen.size.height) - 40.0 - DMCCPanelShift()) / gCCScale);' $S"
check "Menu Bar Size: a scene made a window (or full screen) after its request follows the same rule when its frame is set (Zetsu), only a height SpringBoard gave changed, the setter type-checked" \
  "grep -q 'static BOOL DMBarSizeSceneIsWindow(id settings) { return DMBarSizeSceneWindowState(settings) == 1; }' $S && grep -q 'double want = state == 1 ? stock : sized, from = state == 1 ? sized : stock;' $S && grep -q 'if (fabs(h - from) < 0.25) {' $S && grep -q 'strcmp(method_getTypeEncoding(sm) ?: \"\", \"v32@0:8d16q24\")) return;' $S && grep -q 'const char \*t = \"v48@0:8{CGRect={CGPoint=dd}{CGSize=dd}}16\";' $S && grep -q 'if (DMBarSizeOwns(frames, NO, \"setFrame:\", t)) {' $S && grep -q '    DMBarSizeSceneFrameSet(self);' $S && grep -q 'frames = objc_getClass(\"FBSSceneSettings\");   // (17+: the base class' $S"
check "Menu Bar Size: the later frame rule's setter hooked at the start or at the first scene request (17+: FrontBoardServices adds it with the first scene settings object), never looked for on a timer (2eebb39's once-a-second lookup gone)" \
  "awk '/^static void DMBarSizeSceneFramesInit\\(BOOL atRequest\\) \\{/{f=1} f&&/dispatch_after|NSTimer|tries/{bad=1} f&&/gDMBarSizeFramesHooked = 1;/{a=1} f&&/gDMBarSizeFramesHooked = -1;/{b=1} f&&/^}/{print (a&&b&&!bad) ? \"ok\" : \"no\"; exit}' $S | grep -q ok && grep -q '    if (!gDMBarSizeFramesHooked) DMBarSizeSceneFramesInit(YES);   // (a request carries' $S && awk '/_modifyApplicationSceneSettings:\\(id\\)settings fromRequestContext/{f=1} f&&/DMBarSizeSceneFramesInit\\(YES\\)/{a=NR} f&&/%orig;/{print (a && a<NR) ? \"ok\" : \"no\"; exit}' $S | grep -q ok && grep -q '    DMBarSizeSceneFramesInit(NO);' $S"
check "Menu Bar Size: iOS's battery -- its five measures (body, pin, outline, corners) and its bolt's scale x the battery's own mark, nothing else of it (the percentage beside it is the bar's text, already at the size)" \
  "grep -q '^- (CGSize)_batterySizeForTraitCollection:(id)traits {' $S && grep -q '^- (CGSize)_pinSizeForTraitCollection:(id)traits {' $S && [ \$(grep -c '    return CGSizeMake(s.width \* k, s.height \* k);' $S) = 2 ] && grep -q '^- (double)_lineWidthAndInterspaceForTraitCollection:(id)traits {' $S && grep -q '    return w \* DMBarSizeBatteryScale(self);' $S && grep -q '^- (double)_outsideCornerRadiusForTraitCollection:(id)traits {' $S && grep -q '^- (double)_insideCornerRadiusForTraitCollection:(id)traits {' $S && [ \$(grep -c '    return r \* DMBarSizeBatteryScale(self);' $S) = 2 ] && grep -q '    return m \* DMBarSizeBatteryScale(self);' $S && ! grep -q '_create_percentView' $S && ! grep -q 'percentView' $S"
check "Menu Bar Size: iOS's battery and static battery marked by their item only when the item's bar took the size (one of the hooked families' providers, not a TV's), read from the item's ivars (its getters make one when nil)" \
  "grep -q '    double k = MSBDMenuBarBatteryScale(gDMBarSize, vp && DMBarSizeSizedProvider(object_getClass(vp)));' $S && grep -q '    if (battery && k != 1.0) objc_setAssociatedObject(battery, kBarSizeBatteryKey, @(k), OBJC_ASSOCIATION_RETAIN_NONATOMIC);' $S && grep -q 'const char \*const names\[2\] = { \"_batteryView\", \"_staticBatteryView\" };   // (the ivars, not the getters' $S && awk '/^static BOOL DMBarSizeSizedProvider\\(Class c\\) \\{/{f=1} f&&/if \\(!DMBarSizeClass\\(c\\)\\) return NO;/{a=1} f&&/gDMBarSizedPad\\[0\\] && \\[c isSubclassOfClass:gDMBarSizedPad\\[0\\]\\]/{b=1} f&&/^}/{print (a&&b) ? \"ok\" : \"no\"; exit}' $S | grep -q ok && grep -q '        gDMBarSizedPad\[f\] = pad;' $S && grep -q '        gDMBarSizedPad\[0\] = gDMBarSizedPad\[1\] = Nil;' $S && [ \$(grep -c '    DMBarSizeBatteryMade(self);' $S) = 2 ]"
check "Menu Bar Size: iOS's battery hooks all or none, each method its own with the types read, on the family of SpringBoard's own bars (17+: SystemStatusUI's item, its battery's and static battery's bolts), only once the size is in force" \
  "awk '/^static void DMBarSizeBatteryInit\\(BOOL stui\\) \\{/{f=1} f&&/DMBarSizeOwns\\(view, NO, \"_batterySizeForTraitCollection:\", size\\) && DMBarSizeOwns\\(view, NO, \"_pinSizeForTraitCollection:\", size\\)/{a=1} f&&/DMBarSizeOwns\\(view, NO, \"_insideCornerRadiusForTraitCollection:\", measure\\) && DMBarSizeOwns\\(bolt, NO, \"_batteryBoltScaleFactorMultiplier\", \"d16@0:8\"\\)/{b=1} f&&/DMBarSizeOwns\\(item, NO, \"_create_batteryView\", \"v16@0:8\"\\) && DMBarSizeOwns\\(item, NO, \"_create_staticBatteryView\", \"v16@0:8\"\\)/{c=1} f&&/if \\(!all\\) \\{/{d=NR} f&&/%init\\(MenuBarSizeBattery, _UIBatteryView = view\\);/{e=NR} f&&/if \\(stillBolt\\) %init\\(MenuBarSizeBatteryStaticBolt, _UIBatteryView = still\\);/{g=1} f&&/^}/{print (a&&b&&c&&d&&e&&g&&d<e) ? \"ok\" : \"no\"; exit}' $S | grep -q ok && grep -q 'bolt = stui ? objc_getClass(\"STUIStatusBarBatteryView\") : view, item = objc_getClass(stui ? \"STUIStatusBarBatteryItem\" : \"_UIStatusBarBatteryItem\");' $S && awk '/^static void DMBarSizeInit\\(void\\) \\{/{f=1} f&&/DM_FEATURE_MARK\\(\"menubar-size\"\\);/{a=NR} f&&/    DMBarSizeBatteryInit\\(stui\\);/{b=NR} f&&/^}/{print (a&&b&&a<b) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
check "Menu Bar Size: a TV keeps the normal bar's geometry (24)" "grep -q 'CGFloat dh = dock ? dock.doubleValue : round(size.height \\* 0.2), top = 24.0;' $S && grep -q ': 24.0;' $S"
check "Settings: Menu Bar Size in the Status Bar group (hidden with the stock bar), Small / Medium / Large = 0 / 1 / 2, Small by default" \
  "python3 -c \"
import plistlib,sys
items=plistlib.load(open('$P/Resources/Root.plist','rb'))['items']
i=[n for n,x in enumerate(items) if x.get('key')=='menuBarSize'][0]; r=items[i]
g=[x for x in items[:i] if x.get('cell')=='PSGroupCell'][-1]
ok=r['cell']=='PSLinkListCell' and r['detail']=='PSListItemsController' and r['validTitles']==['Small','Medium','Large'] and r['validValues']==[0,1,2] and r['default']==0 and g.get('label')=='Status Bar' and g.get('stockHides') is True and items[i+1].get('key')=='autoHideStatusBar'
sys.exit(0 if ok else 1)\""
check "Settings: a change offers the respring; anything stored that is not 1 or 2 shows as Small, as SpringBoard reads it" \
  "grep -q 'if (\\[\\[specifier propertyForKey:@\"key\"\\] isEqual:@(kMSBDMenuBarSizeKey)\\]) return @(MSBMenuBarSizeStored());' $P/MSBRootListController.m && grep -q '\\[self msb_menuBarSizeChanged:size\\];' $P/MSBRootListController.m && grep -q 'return MSBDMenuBarSizeFrom(isNumber, d);' $P/MSBRootListController.m"
check "crash guard: a crash in the size's hooks (iOS's battery's too) sets it back to Small (menuBarSize 0), not the stock status bar" \
  "grep -q '^target menuBarSize pref com.besiktasliseba.macstatusbar menuBarSize 0 0 ' crashmap-rules.txt && grep -qF 'sym MacStatusBarCore \\\$MenuBarSize(UIKit|STUI|Scenes|SceneFrames|Grabber|Battery|BatteryBolt|BatteryStaticBolt|BatteryItem)(Clock)?\\\$ menuBarSize' crashmap-rules.txt"
check "Menu Bar Size: a window's scene keeps iOS's own status bar height, a scene under the bar the size's (told in the scene's own coordinate space, its settings' -bounds, not the frame's origin; the hook type-checked, only once the size is in force)" \
  "grep -q 'return MSBDSceneIsWindow(MSBDSceneShortfall(own.size.height, b.size.width, b.size.height, o)) ? 1 : 0;' $S && grep -q 'CGRect own = ((CGRect (\*)(id, SEL))objc_msgSend)(settings, bs), b = ((CGRect (\*)(id, SEL))objc_msgSend)(disp, bs);' $S && ! grep -q 'MSBDSceneTopGap' $S && grep -q '    if (window) gDMBarStockDepth++;' $S && grep -q '        if (window) gDMBarStockDepth--;' $S && awk '/^static void DMBarSizeInit\\(void\\) \\{/{f=1} f&&/DM_FEATURE_MARK\\(\"menubar-size\"\\);/{a=NR} f&&/if \\(DMBarSizeOwns\\(handle, NO, \"_modifyApplicationSceneSettings:fromRequestContext:entity:\", \"v40@0:8@16@24@32\"\\)\\) \\{/{b=NR} f&&/%init\\(MenuBarSizeScenes, SBDeviceApplicationSceneHandle = handle\\);/{c=NR} f&&/^}/{print (a&&b&&c&&a<b&&b<c) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
check "Menu Bar Size: iOS's own height of the iPad's bar read from the same provider with the size left out" \
  "awk '/^static CGFloat DMMenuBarHeight\\(void\\) \\{/{f=1} f&&/gDMBarStockDepth\\+\\+;/{a=NR} f&&/gDMMenuBarStockH = \\(\\(double \\(\\*\\)\\(id, SEL\\)\\)objc_msgSend\\)\\(\\(id\\)vc, hs\\);/{b=NR} f&&/gDMBarStockDepth--;/{c=NR} f&&/^}/{print (a&&b&&c&&a<b&&b<c) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
check "Menu Bar Size: the Lock Screen's Control Center grabber goes down by what the size added (its own method, type-checked; a relative top left as it is)" \
  "grep -qF '\"{CGPoint=dd}84@0:8{CGRect={CGPoint=dd}{CGSize=dd}}16d48B56{CGSize=dd}60o^B76\"' $S && grep -qF 'double shift = relative ? 0.0 : DMBarSizeGrabberShift((UIView *)self);' $S && grep -qF 'CGPoint c = %orig(bounds, top + shift, relative, size, constrained);' $S && grep -qF 'return MSBDMenuBarGrabberShift(gDMBarSize, gDMMenuBarH, gDMMenuBarStockH);' $S"
check "Menu Bar Size: Stage Manager windows handed over before the stages' re-fit are re-fitted on the way, their bottom kept -- before the desktop fit moves them down whole" \
  "awk '/^static id DMSMAttrsFitScreen\\(id attrs, id identity, BOOL behindDock, NSString \\*bundle\\) \\{/{f=1} f&&/if \\(DMSMIsMainIdentity\\(identity\\) && DMSMSizeRefitPending\\(&placedTop\\)\\) \\{ id r = DMSMAttrsRefitTop\\(attrs, bundle, NO, YES, placedTop\\); if \\(r\\) attrs = r; \\}/{a=NR} f&&/DMSMFitInDesk\\(/{b=NR} f&&/^}/{print (a&&b&&a<b) ? \"ok\" : \"no\"; exit}' $S | grep -q ok && grep -q 'if (!MSBDMenuBarRefitWanted(placed, gDMMenuBarH, gDMBarSize)) return NO;' $S"
check "Menu Bar Size: an Aerial window's own scene keeps iOS's own status bar height where its frame reaches the app (both FBScene updates, after the frame veto; full screen and Zetsu / MilkyWay4 left)" \
  "[ \$(grep -c '    settings = DMBarSizeAerialWindowSettings(self, settings);' $S) = 2 ] && grep -qF 'if (gDMBarSize == MSBDMenuBarSmall || !(gDMMenuBarStockH > 0) || DMActiveEngine() != DMEngineAerial || !settings) return settings;' $S && grep -qF 'if (DMSceneFrameIsCanvas(f) || !(f.size.width >= 50.0) || !(f.size.height >= 50.0)) return settings;' $S && grep -qF 'if (!sm || strcmp(method_getTypeEncoding(sm) ?: \"\", \"v32@0:8d16q24\")) return settings;' $S && awk '/^- \\(void\\)updateSettings:\\(id\\)settings withTransitionContext:\\(id\\)context \\{/{f=1} f&&/settings = DMVetoFrameHoldApply/{a=NR} f&&/gFullFrameGuardBundle.length && CACurrentMediaTime\\(\\) < gFullFrameGuardUntil && \\[settings respondsToSelector/{b=NR} f&&/settings = DMBarSizeAerialWindowSettings\\(self, settings\\);/{c=NR; print (a&&b&&a<b&&b<c) ? \"ok\" : \"no\"; exit}' $S | grep -q ok"
